import{_ as p,o as e,c as o,ag as a}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第53章 一个名字","description":"","frontmatter":{},"headers":[],"relativePath":"第53章_一个名字.md","filePath":"第53章_一个名字.md"}'),_={name:"第53章_一个名字.md"};function r(n,t,s,u,c,d){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="第53章-一个名字" tabindex="-1">第53章 一个名字 <a class="header-anchor" href="#第53章-一个名字" aria-label="Permalink to &quot;第53章 一个名字&quot;">​</a></h1><p>五月，她开始变成一个名字。</p><p>这件事是她一点一点讲给我听的，讲完我才把它拼起来。先是体检。她说要早上空腹去，她说她四点五十就起来了，五点半在门口站着。她说，医院那个窗口的人问我叫什么，我说了一下，她没听清。我说，然后呢。她说，然后她让我拼。我说，你怎么拼。她说，我就一个字母一个字母地说。她说，我说完了她写下来，写完了把单子推给我看。她说，她打错了一个字母。她说，我发现的时候她已经盖章了。我说，那你去改。她说，改要重新排队，重新开单，重新盖章。她说，我妈说算了。她说，她说反正人家系统里能对上的。她说，我就站在那个窗口前面，看着那张盖了章的单子，上面写着一个跟我有点像的名字。</p><p>我那天下午没课，我在宿舍里坐着，把这整段看了三遍。我说，那你怎么不吵。她隔了很久，说，我吵什么呢。她说，那个字是我自己的名字。她说，可是我已经在那个流程里了。她说，流程里的人不吵，流程里的人等。</p><p>然后是公证。她说要三份材料，翻译件，公章，还要本人到场。她说本人到场那条是可以不通本人的。我说，什么意思。她说，就是有亲属可以代。我说，那你去不去。她说，我妈去。她说，我妈去了，人家说她不懂，得找个人帮忙跑。她说，然后她想起来我认识你。那一段她讲得很简单：那天下午三点，她的一个亲戚在公证处门口给一个陌生的号码打电话，那个号码打到了她那里，她转给我。电话里那个人说，你是她同学吧，你来一趟，帮忙排个队，材料我送过去。我说，好。我说完这句，我妈在客厅听见了，问，谁。我说，同学，让我去帮个忙。我妈说，什么忙。我说，排队。我妈没说话。我妈那个人，她不说&quot;你别去&quot;，她就&quot;哦&quot;一声。那一声&quot;哦&quot;我听了十九年，我知道那是什么。</p><p>三点四十我到了那个大厅。我拿着一张登记本，替一个我从来没在任何场合公开过的名字，站了一个钟头二十分钟。中间有个穿蓝衣服的过来问我，你排哪个窗。我说，我不知道，我帮人排的。他说，帮人排要登记的，你有身份证吗。我把身份证给他，他低头抄，抄完把条子给我。我站在那里，忽然想到一件事：我这一辈子，用我自己的身份证，替她排过一次队。这件事我不能跟任何人说，包括她，因为跟她说，她会难受，她难受了以后会说一句很客气的话，她那些客气话，比什么都远。</p><p>排到第四十分钟的时候，前面一个窗口的人喊我。他问我，你办什么。我说，代办公证。他说，委托书呢。我把那个信封给他，他翻了四下，把头抬起来。他说，你和当事人什么关系。我说，同学。他把纸放回台子上，说，同学不行。他说，代办公证要直系亲属，要么她本人来。他说，你这个材料白排了。他说，下一个。我拿着那个信封从队伍里走出来，大厅里一百多个人，没人在看。我在柱子边上站了一会儿，把信封放回背包。我出去给她发了条消息，我说排了，材料交上去了，等通知。那六个字我打得很平。我那天撒的谎，是我这一辈子撒得最没技术的一个。</p><p>第二天那个亲戚又打电话来，说她本人来了，十分钟办完。那天她在窗口签字，我在车上。我没去。我回学校以后坐在教室里，把上午那四十分钟又想了一遍。我想的不是那个窗口，我想的是他问我&quot;什么关系&quot;的时候，我嘴里那个&quot;同学&quot;。那个词不是我在照规矩说，那个词就是法律上说的话。我们两个之间，能拿去登记的关系，只有那两个字。</p><p>那天我在条子上看见她写的委托书上的名字。我念了一遍，在心里念的，出声也没有人听见。我念完把条子塞回兜里，继续排。回去以后她上线问我，排得顺利吗。我说，顺利。她说，谢谢你啊。我说，不用。她说，你这个人帮了忙还不用。我说，嗯。她说，你又嗯。我说，我今天有点累。她说，那你早点睡。那天的对话就结束了。</p><p>我躺在床上，把那天所有的事在脑子里过了一遍。我想到的是那个打错的字母，我想，一个人这一辈子最重要的那次改名，是别人打错的，而且没有人管。</p><p>第二天她跟我说了另一件。她说，今天去银行。我说，干什么。她说，存一笔钱，冻结一段时间，证明家里有那个钱。我说，那笔钱是你们的吗。她说，不是。她说，是借的。她说，钱上午进来，下午出去，我在中间坐了一个钟头，看柜员打字。她说，那个钱在这个柜台上放了一个钟头。她说，它 belonged 到一个跟我完全不认识的人名下，然后又走了。她说，那一个钟头里我是有钱人的女儿。她说，一个钟头以后我又不是了。我看到这儿，坐起来，开了灯，我给她打了一句：你别写这种话。她说，我写我一天里的事。我说，你那个英文是刚学的？她说，我随便打的。我说，你随便打的更吓人。她说，为什么。我说，因为你今天太累了，累到你中文都懒得打全。</p><p>她没回。</p><p>过了一会儿她回了一句：你今天讲话怎么这么多。我说，你希望我说什么。她说，我希望你说，你今天吃饭了吗。我说，你今天吃饭了吗。她说，吃了。我说，吃的什么。她说，一根玉米。我说，那不够。她说，够了，我今天不是饿。那天晚上十一点，她最后发了一条：我今天在一个大厅里坐了一整天。她说，我叫了三次号，三次都不是我的名字。她说，有一声特别像我。她说，我抬头了。她说，不是我。我说，嗯。她说，你以后能不能别嗯。我说，好。她说，你答应得太快了。我说，我改。她说，你改不了。她说，你这个人，你连等一个人都能等成一种习惯，你改不掉的。</p><p>那晚她下线之前，最后发的是两个字：晚安。那两个字我等了一年半没有等到过。她自己大概不知道她那天为什么发了。</p>',14)])])}const q=p(_,[["render",r]]);export{l as __pageData,q as default};
